using System;
using System.Collections.Generic;
using System.IO;

public sealed partial class MixerParameter {
 public readonly int Model,Area,Element,Index,Channel,Minimum,Maximum;
 public ulong Key{get{return ((ulong)Model<<28)|((ulong)Area<<21)|((ulong)Element<<14)|((ulong)Index<<7)|(uint)Channel;}}
