 public static MixerParameter Solo(int id){ValidateId(id);return id>=124?null:new MixerParameter(6,3,id<96?0x2E:0x2F,0,id<96?id:id-96,0,1);}
 public static MixerParameter Name(int id,int character){ValidateId(id);if(character<0||character>=20)throw new ArgumentOutOfRangeException();return new MixerParameter(6,2,id<96?4:id<104?15:id<116?16:id<124?17:18,character,id<116?Local(id):id<124?Local(id)/2:0,32,122);}
 public static MixerParameter CardInfo(int slot,int field){if(slot<0||slot>5||field<0||field>2)throw new ArgumentOutOfRangeException();return new MixerParameter(6,4,0x1F,field,slot,0,255);}public static MixerParameter InputSource(int id){if(id<0||id>=96)throw new ArgumentOutOfRangeException();return new MixerParameter(6,2,1,0,id,0,178);}public static MixerParameter SendOn(int id,int aux){ValidateSend(id,aux);return new MixerParameter(127,1,0x23,aux*3,id,0,1);}
 public static MixerParameter SendPre(int id,int aux){ValidateSend(id,aux);return new MixerParameter(127,1,0x23,aux*3+1,id,0,1);}
 public static MixerParameter AuxMode(int aux){if(aux<0||aux>11)throw new ArgumentOutOfRangeException();return new MixerParameter(127,1,0x37,0,aux,0,1);}
 public static MixerParameter SoloActive(){return new MixerParameter(6,4,0x30,1,0,0,1);}
 static void ValidateId(int id){if(id<0||id>125)throw new ArgumentOutOfRangeException();}
 static void ValidateSend(int id,int aux){if(id<0||id>=96||aux<0||aux>=12)throw new ArgumentOutOfRangeException();}
 public static int Local(int id){return id<96?id:id<104?id-96:id<116?id-104:id<124?id-116:id-124;}
 public static string Title(int id){return id<96?"Input "+(id+1):id<104?"Bus "+(id-95):id<116?"Aux "+(id-103):id<124?"Matrix "+((id-116)/2+1)+((id%2)==0?" L":" R"):id==124?"Stereo L":"Stereo R";}
 public byte[] Request(int device){if(device<0||device>15)throw new ArgumentOutOfRangeException();return new byte[]{240,67,(byte)(48|device),62,(byte)Model,(byte)Area,(byte)Element,(byte)Index,(byte)Channel,247};}
 public byte[] Write(int value,int device){if(value<Minimum||value>Maximum||device<0||device>15)throw new ArgumentOutOfRangeException();return new byte[]{240,67,(byte)(16|device),62,(byte)Model,(byte)Area,(byte)Element,(byte)Index,(byte)Channel,(byte)((value>>21)&127),(byte)((value>>14)&127),(byte)((value>>7)&127),(byte)(value&127),247};}
 public static bool Parse(byte[] p,out ulong key,out int value){key=0;value=0;if(p.Length!=14||p[0]!=240||p[1]!=67||(p[2]&240)!=16||p[3]!=62||(p[4]!=6&&p[4]!=127)||p[13]!=247)return false;for(int i=5;i<13;i++)if(p[i]>127)return false;key=((ulong)p[4]<<28)|((ulong)p[5]<<21)|((ulong)p[6]<<14)|((ulong)p[7]<<7)|p[8];value=(p[9]<<21)|(p[10]<<14)|(p[11]<<7)|p[12];return true;}
 static string[] outputLabels;public static string LevelLabel(int id,int? value){if(!value.HasValue)return "Unknown";if(id<96)return FaderProtocol.Label(value.Value);if(outputLabels==null)outputLabels=File.ReadAllLines(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"output-fader-db.txt"));return outputLabels[value.Value];}
 public static void Test(){for(int id=0;id<126;id++){var spec=Level(id,-1);ulong key;int value;if(!Parse(spec.Write(1023,0),out key,out value)||key!=spec.Key||value!=1023)throw new Exception("Mixer level addressing failed");if(id<96){spec=Level(id,11);if(spec.Index!=35||spec.Channel!=id)throw new Exception("Aux send addressing failed");}}if(LevelLabel(124,1023)!="0.00 dB")throw new Exception("Output scale incorrect");if(Solo(116).Channel!=20||Name(117,4).Channel!=0)throw new Exception("Output channel mapping failed");}
}

public sealed class MixerChannelState {
 public int Id;public int? Level,On,Solo,SendOn,Pre,Meter,Pan,Source;public string Name,ShortName;public bool NameComplete;
}

public sealed partial class FaderConnection {
 sealed class Scalar {public int Value;public DateTime Time;}
 readonly Dictionary<ulong,Scalar> extra=new Dictionary<ulong,Scalar>();readonly Dictionary<ulong,MixerParameter> specs=new Dictionary<ulong,MixerParameter>();readonly Dictionary<ulong,KeyValuePair<MixerParameter,int>> changes=new Dictionary<ulong,KeyValuePair<MixerParameter,int>>();
 volatile int mixerView,sendAux=-1;int statusCursor,nameCursor;double nextStatus,nextName,nextMaster,nextLevels,nextExtraWrite,nextOutputMeters,nextGlobal;int activeExtraView=-1,activeExtraAux=-2;
 int[] visibleIds=new int[0];readonly List<MixerParameter> statusReads=new List<MixerParameter>(),nameReads=new List<MixerParameter>();readonly Dictionary<int,int> outputMeters=new Dictionary<int,int>();readonly Dictionary<int,DateTime> outputMeterDates=new Dictionary<int,DateTime>();
 public void SetMixerView(int view,int aux){if(view<0||view>6||aux< -1||aux>11||(view>=4&&aux>=0))throw new ArgumentOutOfRangeException();lock(gate){mixerView=view;sendAux=aux;if(view<4)bank=view*24;}}
 public static int[] ViewIds(int view){int first=view<4?view*24:view==4?96:view==5?104:116;int count=view<4?24:view==5?12:8;int[] ids=new int[count];for(int i=0;i<count;i++)ids[i]=first+i;return ids;}
 MixerParameter Register(MixerParameter p){if(p!=null)specs[p.Key]=p;return p;}
 int? ScalarValue(MixerParameter p,double age){if(p==null)return null;Register(p);Scalar s;return extra.TryGetValue(p.Key,out s)&&(DateTime.UtcNow-s.Time).TotalSeconds<age?(int?)s.Value:null;}
 public int? SoloStatus{get{lock(gate)return ScalarValue(MixerParameter.SoloActive(),5);}}
 public int? AuxModeValue{get{lock(gate)return sendAux<0?null:ScalarValue(MixerParameter.AuxMode(sendAux),5);}}
 public MixerChannelState Channel(int id){lock(gate){int aux=id<96?sendAux:-1;var result=new MixerChannelState{Id=id,Source=id<96?ScalarValue(MixerParameter.InputSource(id),double.PositiveInfinity):null,Level=id<96&&aux<0?Fresh(values,received,id,6):ScalarValue(MixerParameter.Level(id,aux),2),On=ScalarValue(MixerParameter.On(id),5),Solo=ScalarValue(MixerParameter.Solo(id),5),SendOn=aux>=0?ScalarValue(MixerParameter.SendOn(id,aux),5):null,Pre=aux>=0?ScalarValue(MixerParameter.SendPre(id,aux),5):null,Pan=id<96?Fresh(pans,panReceived,id,2):null};if(aux>=0&&ScalarValue(MixerParameter.AuxMode(aux),5)!=0)result.Level=null;if(id<96)result.Meter=Fresh(meters,meterReceived,id,1);else{DateTime date;int meter;if(outputMeters.TryGetValue(id,out meter)&&outputMeterDates.TryGetValue(id,out date)&&(DateTime.UtcNow-date).TotalSeconds<1)result.Meter=meter;}char[] name=new char[16],shortName=new char[4];bool full=true,shortFull=true;for(int i=0;i<16;i++){int? c=ScalarValue(MixerParameter.Name(id,i+4),120);if(!c.HasValue){full=false;break;}name[i]=(char)c.Value;}for(int i=0;i<4;i++){int? c=ScalarValue(MixerParameter.Name(id,i),120);if(!c.HasValue){shortFull=false;break;}shortName[i]=(char)c.Value;}result.ShortName=shortFull?new string(shortName).TrimEnd():null;result.Name=full?new string(name).TrimEnd():result.ShortName;result.NameComplete=full&&shortFull;return result;}}
 static int? Fresh(int?[] data,DateTime[] dates,int i,double age){return (DateTime.UtcNow-dates[i]).TotalSeconds<age?data[i]:null;}
 public void SetLevel(int id,int raw){lock(gate){if(id<96&&sendAux<0){WriteFader(id,raw);return;}Queue(MixerParameter.Level(id,id<96?sendAux:-1),raw,2);}}
 public void SetMute(int id,bool muted){lock(gate)Queue(MixerParameter.On(id),muted?0:1,5);}
 public void SetSolo(int id,bool solo){lock(gate){var spec=MixerParameter.Solo(id);if(spec==null)throw new InvalidOperationException("Stereo master has no solo control.");Queue(spec,solo?1:0,5);}}
 public void SetSendOn(int id,bool enabled){lock(gate)Queue(MixerParameter.SendOn(id,sendAux),enabled?1:0,5);}
 public void SetSendPre(int id,bool pre){lock(gate)Queue(MixerParameter.SendPre(id,sendAux),pre?1:0,5);}
 public void Rename(int id,string text){Rename(id,text,Channel(id).ShortName);}public void Rename(int id,string text,string shortText){if(text==null||text.Length>16||shortText==null||shortText.Length>4)throw new ArgumentException("Use up to 16 characters for the name and 4 for its abbreviation.");foreach(char c in text+shortText)if(c<32||c>122)throw new ArgumentException("The desk supports characters from space through z.");lock(gate){if(!Channel(id).NameComplete)throw new InvalidOperationException("Wait for the desk names to load.");string padded=shortText.PadRight(4)+text.PadRight(16);for(int i=0;i<20;i++)if(!ScalarValue(MixerParameter.Name(id,i),120).HasValue)throw new InvalidOperationException("Name readback is incomplete.");for(int i=0;i<20;i++)Queue(MixerParameter.Name(id,i),padded[i],120);}} void Queue(MixerParameter p,int value,double age){if(stopping||error!=null||p==null||!ScalarValue(p,age).HasValue)throw new InvalidOperationException("This control is waiting for current console data.");p.Write(value,device);changes[p.Key]=new KeyValuePair<MixerParameter,int>(p,value);}
 void ExtraPacket(byte[] packet){ulong key;int value;if(MixerParameter.Parse(packet,out key,out value)){lock(gate){MixerParameter spec;if(specs.TryGetValue(key,out spec)&&value>=spec.Minimum&&value<=spec.Maximum){RoutingPacket(spec,value);extra[key]=new Scalar{Value=FreezeStartupValue(spec,value),Time=DateTime.UtcNow};}}}if(packet.Length<12||packet[4]!=6||packet[5]!=33||packet[7]!=0||packet[6]<1||packet[6]>4||(packet.Length-10)%2!=0)return;int group=packet[6],first=packet[8],count=(packet.Length-10)/2,limit=group==1?8:group==2?12:group==3?8:2;if(first+count>limit)return;lock(gate)for(int i=0;i<count;i++){int id=(group==1?96:group==2?104:group==3?116:124)+first+i;outputMeters[id]=(packet[9+2*i]<<7)|packet[10+2*i];outputMeterDates[id]=DateTime.UtcNow;}}
 void PrepareExtra(){visibleIds=ViewIds(mixerView);statusReads.Clear();nameReads.Clear();foreach(int id in visibleIds){statusReads.Add(Register(MixerParameter.On(id)));var solo=Register(MixerParameter.Solo(id));if(solo!=null)statusReads.Add(solo);if(sendAux>=0){statusReads.Add(Register(MixerParameter.SendOn(id,sendAux)));statusReads.Add(Register(MixerParameter.SendPre(id,sendAux)));}for(int i=0;i<20;i++)nameReads.Add(Register(MixerParameter.Name(id,i)));Register(MixerParameter.Level(id,id<96?sendAux:-1));}statusReads.Add(Register(MixerParameter.SoloActive()));for(int id=124;id<=125;id++){Register(MixerParameter.Level(id,-1));statusReads.Add(Register(MixerParameter.On(id)));for(int i=0;i<20;i++)nameReads.Add(Register(MixerParameter.Name(id,i)));}if(sendAux>=0)statusReads.Add(Register(MixerParameter.AuxMode(sendAux)));nameReads.Sort(delegate(MixerParameter a,MixerParameter b){int rank=(a.Index<4?0:1).CompareTo(b.Index<4?0:1);if(rank!=0)return rank;rank=a.Element.CompareTo(b.Element);if(rank!=0)return rank;rank=a.Channel.CompareTo(b.Channel);return rank!=0?rank:a.Index.CompareTo(b.Index);});activeExtraView=mixerView;activeExtraAux=sendAux;statusCursor=nameCursor=0;nextStatus=nextName=nextMaster=nextLevels=nextOutputMeters=0;}
 void TickExtra(FaderReader output,double now){lock(gate){if(activeExtraView!=mixerView||activeExtraAux!=sendAux){PrepareExtra();output.ReadParameter(MixerParameter.SoloActive(),device);if(sendAux>=0)output.ReadParameter(MixerParameter.AuxMode(sendAux),device);}if(stopping)return;PollStartupMetadata(output,now);TickRouting(output,now);TickZeroInputs(output,now);if(now>=nextExtraWrite){int n=0;var keys=new List<ulong>(changes.Keys);foreach(ulong key in keys){var change=changes[key];changes.Remove(key);output.SetParameter(change.Key,change.Value,device);output.ReadParameter(change.Key,device);if(++n>=8)break;}nextExtraWrite=now+20;}if(now>=nextStatus){for(int i=0;i<2;i++){MixerParameter selected=null;for(int j=0;j<statusReads.Count;j++){var p=statusReads[(statusCursor++)%statusReads.Count];Scalar sample;if(!extra.TryGetValue(p.Key,out sample)||(DateTime.UtcNow-sample.Time).TotalSeconds>1){selected=p;break;}}if(selected!=null)output.ReadParameter(selected,device);}nextStatus=now+50;}if(now>=nextName){for(int tried=0;tried<nameReads.Count;tried++){var p=nameReads[(nameCursor++)%nameReads.Count];Scalar sample;if(!extra.TryGetValue(p.Key,out sample)||(DateTime.UtcNow-sample.Time).TotalSeconds>30){output.ReadParameter(p,device);break;}}nextName=now+20;}if(now>=nextGlobal){output.ReadParameter(MixerParameter.SoloActive(),device);if(sendAux>=0)output.ReadParameter(MixerParameter.AuxMode(sendAux),device);nextGlobal=now+500;}if(now>=nextMaster){for(int id=124;id<=125;id++)output.ReadParameter(MixerParameter.Level(id,-1),device);nextMaster=now+100;}if((mixerView>=4||sendAux>=0)&&now>=nextLevels){foreach(int id in visibleIds)output.ReadParameter(MixerParameter.Level(id,id<96?sendAux:-1),device);nextLevels=now+60;}if(now>=nextOutputMeters){output.SubscribeOutputMeters(4,2,device);if(mixerView>=4){int group=mixerView-3;output.SubscribeOutputMeters(group,group==2?12:8,device);}nextOutputMeters=now+5000;}}}
 void ClearExtra(){changes.Clear();extra.Clear();outputMeters.Clear();outputMeterDates.Clear();}
}









